INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7e91e7baef4f529391f2','Amedex 2023.pdf','400','Mixed/Unclassified','All of the following situations allow the doctor-patient confidentiality to be breached except:','{"A":"When the patient consents to allow personal details to be revealed to a third party.","B":"If there are other health professionals who have a legitimate therapeutic interest in the care of the patient\nincluding medical students.","C":"If there are other health professionals who have a legitimate therapeutic interest in the care of the patient\nexcluding medical students.","D":"If there is overriding public interest.","E":"Where disclosure of the information is required or permitted by operation of the law."}','B','For a proper doctor-patient relationship it is important to ensure that information provided by patients to the treating
doctor will remain strictly confidential.
The general rule is that doctors may not, without the consent of their patients, disclose to any third party information
acquired in the course of their professional relationship. This rule of confidentiality extends also to disclosure to
family members.
However, there are exceptions where confidentiality can be breached. These exceptions are as follows:
Where the patient gives valid consent for his/her medical information to be revealed to a third party - e.g. the patient
asks you to reveal his medical information to his/her employer, insurance company, etc.
Sharing information in the healthcare team - in many health care situations, consent for sharing confidential
information between members of the ‘health-care team’ is implied and it is presumed that patients know and accept
that this will happen. These members include other health professionals who have a legitimate therapeutic interest
in the care of the patient. Medical students cannot be considered legitimate in this sense and are excluded, unless
the patient consents to. In fact, medical students should be considered thirds parties.
Exceptions established by law - these include the notification of infectious diseases, births and deaths, and deaths
reportable to the coroner. In some states, doctors are obliged to notify the relevant registration authority if a health-
care professional, who is a patient, is ill and the community is believed to be at risk; this exception is backed by
immunity from civil action.
Overriding community interest - when community interest overrides that of the patient, disclosure of the patient’s
medical information is not considered a breach of confidentiality. An example is when a doctor advise the police of
a patient they believe should not be driving a motor vehicle, or a psychiatrist believes a patient is a serious threat to
others.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"976","duplicate_group_id":"exact-d67c8e968efa","duplicate_sources":[{"record_id":"7e91e7baef4f529391f2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":400,"source_qid":"976"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"7e91e7baef4f529391f2","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":400,"source_qid":"976","domain_hint":"Mixed/Unclassified","stem":"All of the following situations allow the doctor-patient confidentiality to be breached except:","options":{"A":"When the patient consents to allow personal details to be revealed to a third party.","B":"If there are other health professionals who have a legitimate therapeutic interest in the care of the patient\nincluding medical students.","C":"If there are other health professionals who have a legitimate therapeutic interest in the care of the patient\nexcluding medical students.","D":"If there is overriding public interest.","E":"Where disclosure of the information is required or permitted by operation of the law."},"source_answer":"B","source_explanation":"For a proper doctor-patient relationship it is important to ensure that information provided by patients to the treating\ndoctor will remain strictly confidential.\nThe general rule is that doctors may not, without the consent of their patients, disclose to any third party information\nacquired in the course of their professional relationship. This rule of confidentiality extends also to disclosure to\nfamily members.\nHowever, there are exceptions where confidentiality can be breached. These exceptions are as follows:\nWhere the patient gives valid consent for his/her medical information to be revealed to a third party - e.g. the patient\nasks you to reveal his medical information to his/her employer, insurance company, etc.\nSharing information in the healthcare team - in many health care situations, consent for sharing confidential\ninformation between members of the ‘health-care team’ is implied and it is presumed that patients know and accept\nthat this will happen. These members include other health professionals who have a legitimate therapeutic interest\nin the care of the patient. Medical students cannot be considered legitimate in this sense and are excluded, unless\nthe patient consents to. In fact, medical students should be considered thirds parties.\nExceptions established by law - these include the notification of infectious diseases, births and deaths, and deaths\nreportable to the coroner. In some states, doctors are obliged to notify the relevant registration authority if a health-\ncare professional, who is a patient, is ill and the community is believed to be at risk; this exception is backed by\nimmunity from civil action.\nOverriding community interest - when community interest overrides that of the patient, disclosure of the patient’s\nmedical information is not considered a breach of confidentiality. An example is when a doctor advise the police of\na patient they believe should not be driving a motor vehicle, or a psychiatrist believes a patient is a serious threat to\nothers.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d67c8e968efa41f5be248b25bf14040a65d7097c","duplicate_group_id":"exact-d67c8e968efa","duplicate_sources":[{"record_id":"7e91e7baef4f529391f2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":400,"source_qid":"976"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
