INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('549b3bc09d9d872d146f','Amedex 2023.pdf','405','Mixed/Unclassified','You are a medical officer in a tertiary hospital. A patient is about to undergo abdominal surgery. When the patient is
being transferred to the operating theatre, the nurse informs you that the consent for the surgery has not yet been
obtained. Which one of the following is the most appropriate step regarding consent?','{"A":"Send the patient to the operating room and ask the anesthesiologist to obtain the consent.","B":"Obtain the consent yourself and send the patient for the surgery.","C":"Download information from the internet and discuss it with the patient and obtain consent.","D":"Call the treating surgeon and ask him to obtain consent.","E":"Ask the attending nurse to obtain consent from the patient on his way to the operating theatre."}','D','The ultimate responsibility of obtaining consent is with the clinician directly in charge of the treatment; therefore, the
operating surgeon should be called for obtaining consent from the patient. However, it is possible for that clinician to
delegate authority to other healthcare professionals,such as more junior members of staff. The proviso for such
delegation is that the person obtaining consent must be fully equipped to deal with the consent process.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"605","duplicate_group_id":"exact-b7c9e4c9b5c3","duplicate_sources":[{"record_id":"549b3bc09d9d872d146f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":405,"source_qid":"605"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"549b3bc09d9d872d146f","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":405,"source_qid":"605","domain_hint":"Mixed/Unclassified","stem":"You are a medical officer in a tertiary hospital. A patient is about to undergo abdominal surgery. When the patient is\nbeing transferred to the operating theatre, the nurse informs you that the consent for the surgery has not yet been\nobtained. Which one of the following is the most appropriate step regarding consent?","options":{"A":"Send the patient to the operating room and ask the anesthesiologist to obtain the consent.","B":"Obtain the consent yourself and send the patient for the surgery.","C":"Download information from the internet and discuss it with the patient and obtain consent.","D":"Call the treating surgeon and ask him to obtain consent.","E":"Ask the attending nurse to obtain consent from the patient on his way to the operating theatre."},"source_answer":"D","source_explanation":"The ultimate responsibility of obtaining consent is with the clinician directly in charge of the treatment; therefore, the\noperating surgeon should be called for obtaining consent from the patient. However, it is possible for that clinician to\ndelegate authority to other healthcare professionals,such as more junior members of staff. The proviso for such\ndelegation is that the person obtaining consent must be fully equipped to deal with the consent process.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"b7c9e4c9b5c32bcef275431b23870d5c5bd5c79d","duplicate_group_id":"exact-b7c9e4c9b5c3","duplicate_sources":[{"record_id":"549b3bc09d9d872d146f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":405,"source_qid":"605"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
