INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('ec7827779c4635b5c67f','Amedex 2023.pdf','413','Mixed/Unclassified','You have a patient with severe multiple sclerosis that is advanced and progressive, who now has developed renal
failure secondary to diabetes. The patient is alert and has elected to put the DNR order in place at her own
discretion. Today, he has presented for follow-up and you notive that he has a markedly elevated serum potassium
of 8 mmol/L. Which one of the following is the most appropriate management of this patient?','{"A":"Dialysis cannot be done because of the DNR order.","B":"You can do the dialysis if the DNR is reversed for the procedure.","C":"Proceed with the dialysis; ignore the DNR order.","D":"Give insulin and glucose until the DNR status is discussed with the family.","E":"Seek a court order to overrule the DNR order."}','C','A "Do Not-Resuscitate'' (DNR) order is very specifically defined as refraining from resuscitative efforts, such as chest
compression, antiarrhythmic medications (e.g. amiodarone, atropine, adrenaline, etc.), and electrical cardioversion in
the event of the patient’s cardiopulmonary arrest. A DNR order has nothing to do with any other forms of care the
patient is receiving.
DNR order has no impact on the use of dialysis, and DNR order should be ignored when assessing the patient for
dialysis. Hyperkalemia is life-threatening. It is not reasonable to use an inferior therapy such as insulin and glucose
or resins for management of hyperkalemia when dialysis is indicated. In this scenario, DNR order should be ignored
and dialysis performed after obtaining the patient’s consent. The patient, however, still has every right to refuse the
dialysis. This is different from the DNR order.
This patient is awake, alert and able to understand his own medical condition; therefore, the patient’s family is not
relevant in the process of decision making if the patient has the capacity to understand his or her own medical
condition.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1083","duplicate_group_id":"exact-025aa68ac93b","duplicate_sources":[{"record_id":"ec7827779c4635b5c67f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":413,"source_qid":"1083"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"ec7827779c4635b5c67f","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":413,"source_qid":"1083","domain_hint":"Mixed/Unclassified","stem":"You have a patient with severe multiple sclerosis that is advanced and progressive, who now has developed renal\nfailure secondary to diabetes. The patient is alert and has elected to put the DNR order in place at her own\ndiscretion. Today, he has presented for follow-up and you notive that he has a markedly elevated serum potassium\nof 8 mmol/L. Which one of the following is the most appropriate management of this patient?","options":{"A":"Dialysis cannot be done because of the DNR order.","B":"You can do the dialysis if the DNR is reversed for the procedure.","C":"Proceed with the dialysis; ignore the DNR order.","D":"Give insulin and glucose until the DNR status is discussed with the family.","E":"Seek a court order to overrule the DNR order."},"source_answer":"C","source_explanation":"A \"Do Not-Resuscitate'' (DNR) order is very specifically defined as refraining from resuscitative efforts, such as chest\ncompression, antiarrhythmic medications (e.g. amiodarone, atropine, adrenaline, etc.), and electrical cardioversion in\nthe event of the patient’s cardiopulmonary arrest. A DNR order has nothing to do with any other forms of care the\npatient is receiving.\nDNR order has no impact on the use of dialysis, and DNR order should be ignored when assessing the patient for\ndialysis. Hyperkalemia is life-threatening. It is not reasonable to use an inferior therapy such as insulin and glucose\nor resins for management of hyperkalemia when dialysis is indicated. In this scenario, DNR order should be ignored\nand dialysis performed after obtaining the patient’s consent. The patient, however, still has every right to refuse the\ndialysis. This is different from the DNR order.\nThis patient is awake, alert and able to understand his own medical condition; therefore, the patient’s family is not\nrelevant in the process of decision making if the patient has the capacity to understand his or her own medical\ncondition.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","diabetes","management","therapy"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"025aa68ac93bc89524e33117f0ef80a67eb61c59","duplicate_group_id":"exact-025aa68ac93b","duplicate_sources":[{"record_id":"ec7827779c4635b5c67f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":413,"source_qid":"1083"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=e