INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f57eae19a797e8d6b616','Amedex 2023.pdf','416','Mixed/Unclassified','A patient with Alzheimer disease from a skilled-nursing facility is admitted to the hospital for severe upper
gastrointestinal bleeding. The bleeding has not stopped despite multiple transfusions, octreotide, proton ump
inhibitors, and endoscopy. He needs monitoring and evaluation in an intensive care unit. The patient has a DNR order
in place by his legal guardian. Which one of the following is correct regarding this situation?','{"A":"Reverse the DNR order and transfer to the ICU as needed.","B":"He cannot be DNR and be in the ICU.","C":"Transfer to the ICU as needed; it is okay to be DNR in the ICU.","D":"He can go to the ICU with the DNR but cannot go for surgery.","E":"He can go to the ICU with the DNR but cannot be intubated."}','C','A ‘Do Not Resuscitate’ or DNR order means no cardiopulmonary resuscitative efforts if the patients suffers a
cardiopulmonary arrest. There is no other automatic limitation in therapy besides this. DNR orders are often
confused with generalized withholding of care such as transfusion or ICU admission. DNR orders are not the same
as stopping the active management of the patient. DNR orders do not automatically mean that the patient is
immediately terminal or that there is an automatic assumption of palliative care only. This patient should be
transferred to the ICU, but in case CPR is indicated, it should be withheld.
Intubation, surgery, and any other form of treatment can be given to this patient as long as he is not in
cardiopulmonary arrest.
NOTE - When the patient has a cardiopulmonary arrest, it is always presumed that the patient has given consent
to CPR unless the patient has specifically and expressively refused this therapy in advance. In other words, you
do not need to ask for consent from anybody regarding CPR unless the patient is already DNR.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1085","duplicate_group_id":"exact-4d5d77663183","duplicate_sources":[{"record_id":"f57eae19a797e8d6b616","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":416,"source_qid":"1085"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"f57eae19a797e8d6b616","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":416,"source_qid":"1085","domain_hint":"Mixed/Unclassified","stem":"A patient with Alzheimer disease from a skilled-nursing facility is admitted to the hospital for severe upper\ngastrointestinal bleeding. The bleeding has not stopped despite multiple transfusions, octreotide, proton ump\ninhibitors, and endoscopy. He needs monitoring and evaluation in an intensive care unit. The patient has a DNR order\nin place by his legal guardian. Which one of the following is correct regarding this situation?","options":{"A":"Reverse the DNR order and transfer to the ICU as needed.","B":"He cannot be DNR and be in the ICU.","C":"Transfer to the ICU as needed; it is okay to be DNR in the ICU.","D":"He can go to the ICU with the DNR but cannot go for surgery.","E":"He can go to the ICU with the DNR but cannot be intubated."},"source_answer":"C","source_explanation":"A ‘Do Not Resuscitate’ or DNR order means no cardiopulmonary resuscitative efforts if the patients suffers a\ncardiopulmonary arrest. There is no other automatic limitation in therapy besides this. DNR orders are often\nconfused with generalized withholding of care such as transfusion or ICU admission. DNR orders are not the same\nas stopping the active management of the patient. DNR orders do not automatically mean that the patient is\nimmediately terminal or that there is an automatic assumption of palliative care only. This patient should be\ntransferred to the ICU, but in case CPR is indicated, it should be withheld.\nIntubation, surgery, and any other form of treatment can be given to this patient as long as he is not in\ncardiopulmonary arrest.\nNOTE - When the patient has a cardiopulmonary arrest, it is always presumed that the patient has given consent\nto CPR unless the patient has specifically and expressively refused this therapy in advance. In other words, you\ndo not need to ask for consent from anybody regarding CPR unless the patient is already DNR.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","cpr","management","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"4d5d77663183117b17fec540f2126559f382e7fa","duplicate_group_id":"exact-4d5d77663183","duplicate_sources":[{"record_id":"f57eae19a797e8d6b616","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":416,"source_qid":"1085"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.optio