INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('03a4ac974a64a8cd064d','Amedex 2023.pdf','418','Mixed/Unclassified','An 86-year-old woman with longstanding history of chronic obstructive pulmonary disease (COPD) has an advance
directive of DNR (do not resuscitate) order in place. She is now in the emergency department with a femoral neck
fracture sustained at home. She is drowsy and disoriented. Her son and daughter are in the emergency department
asking you to do whatever it takes to treat her. Which one of the following should be your next appropriate action?','{"A":"Inform her son and daughter that she will be given all necessary treatment.","B":"Wait until she regains her consciousness and discuss the matter with her.","C":"Inform your senior doctor.","D":"Inform her son and daughter that there is nothing you can do as she is DNR.","E":"Refer the case to Guardianship Tribunal."}','A','A "Do Not Resuscitate" (DNR) order means if the patient dies i.e. cardiopulmonary arrest, the treating physician(s)
does not perform chest compressions, attempt electrical cardioversion, or use acute antiarrhythmic medications. In
other words, DNR is defined as not attempting any treatment once the patient is dead, indicated by loss of pulse,
blood pressure and spontaneous breathing. DNR orders cannot be considered valid and should not be followed
unless the patient loses all of these.
The most common misunderstanding about DNR is that being DNR must mean the patient is preterminal and is just
about to die. Another common misunderstanding is that a person who is DNR should not get other aspects of an
appropriate medical treatment and care such as biopsies, surgeries, or dialysis.
DNR does not mean that the patient should let be dead just because a DNR order is in place. DNR just means that
the treating physician should consider death as the end point of life and take no further actions to reverse it.
Therefore, DNR is not valid until the patient is clinically dead evident by loss of pulse, blood pressure and the ability
to breath spontaneously.
This patient has a DNR order in place, but she is still clinically alive. She has a femoral neck fracture and the DNR
does not preclude an appropriate medical management of her current condition. She is not conscious now, but her
next of kin can decide on her behalf. As they have given you the consent to proceed with treatment at your discretion,
the next appropriate action is telling them that you will give her all necessary treatments in her best interest.
There is no need to inform the senior doctor, nor referring the case to Guardianship Tribunal, as the path is clear and
there is no conflict over the patient’s best interest in this scenario.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1087","duplicate_group_id":"exact-883a0d485dc5","duplicate_sources":[{"record_id":"03a4ac974a64a8cd064d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":418,"source_qid":"1087"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"03a4ac974a64a8cd064d","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":418,"source_qid":"1087","domain_hint":"Mixed/Unclassified","stem":"An 86-year-old woman with longstanding history of chronic obstructive pulmonary disease (COPD) has an advance\ndirective of DNR (do not resuscitate) order in place. She is now in the emergency department with a femoral neck\nfracture sustained at home. She is drowsy and disoriented. Her son and daughter are in the emergency department\nasking you to do whatever it takes to treat her. Which one of the following should be your next appropriate action?","options":{"A":"Inform her son and daughter that she will be given all necessary treatment.","B":"Wait until she regains her consciousness and discuss the matter with her.","C":"Inform your senior doctor.","D":"Inform her son and daughter that there is nothing you can do as she is DNR.","E":"Refer the case to Guardianship Tribunal."},"source_answer":"A","source_explanation":"A \"Do Not Resuscitate\" (DNR) order means if the patient dies i.e. cardiopulmonary arrest, the treating physician(s)\ndoes not perform chest compressions, attempt electrical cardioversion, or use acute antiarrhythmic medications. In\nother words, DNR is defined as not attempting any treatment once the patient is dead, indicated by loss of pulse,\nblood pressure and spontaneous breathing. DNR orders cannot be considered valid and should not be followed\nunless the patient loses all of these.\nThe most common misunderstanding about DNR is that being DNR must mean the patient is preterminal and is just\nabout to die. Another common misunderstanding is that a person who is DNR should not get other aspects of an\nappropriate medical treatment and care such as biopsies, surgeries, or dialysis.\nDNR does not mean that the patient should let be dead just because a DNR order is in place. DNR just means that\nthe treating physician should consider death as the end point of life and take no further actions to reverse it.\nTherefore, DNR is not valid until the patient is clinically dead evident by loss of pulse, blood pressure and the ability\nto breath spontaneously.\nThis patient has a DNR order in place, but she is still clinically alive. She has a femoral neck fracture and the DNR\ndoes not preclude an appropriate medical management of her current condition. She is not conscious now, but her\nnext of kin can decide on her behalf. As they have given you the consent to proceed with treatment at your discretion,\nthe next appropriate action is telling them that you will give her all necessary treatments in her best interest.\nThere is no need to inform the senior doctor, nor referring the case to Guardianship Tribunal, as the path is clear and\nthere is no conflict over the patient’s best interest in this scenario.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"883a0d485dc57dce1be1bc896fc57e4ca96e7f41","duplicate_group_id":"exact-883a0d485dc5","duplicate_sources":[{"record_id":"03a4ac974a64a8cd064d","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":418,"source_qid":"1087"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
