INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8a6c4bf2005bd7831368','Amedex 2023.pdf','431','Mixed/Unclassified','You are a surgeon in the emergency department. A 71-year-old man with documented history of Alzheimer disease,
who lives with his daughter, is brought to you. The patient is confused, cannot communicate with you, and does not
appear to understand the situation. He is in urgent need for an immediate colostomy. You try to reach his daughter
on the phone for consent but she is not available. Which one of the following is the most appropriate next step in
management?','{"A":"Proceed with the surgery.","B":"Wait until you can find the daughter and obtain consent.","C":"Do not perform the surgery.","D":"Perform the surgery after signatures from two other doctors.","E":"Apply the case to the court for guardianship."}','A','In emergency situations, when the patient is permanently or temporarily unable to give consent, and there is no carer
or guardian or next of kin available to obtain consent from, and delaying the treatment will pose risk to patient’s
health, treatment can be provided without consent. This is based on the principle of duty of care and the patient’s
best interest, and assuming that the patient’s or his/her carer would consent to treatment if he/she was present.
However, if there is an advanced care directive made in the past by the patients, the instruction contained in that
must be followed.
(Option B) In emergency situations, slightest delay may be associated with increased risks to the patient’s health;
therefore, wasting time waiting for the daughter to arrive for consent would be inappropriate.
(Option C) While this patient is in need for emergency treatment, deferring the surgery is not appropriate.
(Option D) You are the healthcare professional responsible for the care and health of the patient and no approval
from other doctors is required.
(Option E) Application of the case to the guardianship court in instances where a patient is in need for emergency
treatment is not appropriate, as delay in treatment is against duty of care and the patient’s best interest.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1191","duplicate_group_id":"exact-cbb2224474c4","duplicate_sources":[{"record_id":"8a6c4bf2005bd7831368","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":431,"source_qid":"1191"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"8a6c4bf2005bd7831368","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":431,"source_qid":"1191","domain_hint":"Mixed/Unclassified","stem":"You are a surgeon in the emergency department. A 71-year-old man with documented history of Alzheimer disease,\nwho lives with his daughter, is brought to you. The patient is confused, cannot communicate with you, and does not\nappear to understand the situation. He is in urgent need for an immediate colostomy. You try to reach his daughter\non the phone for consent but she is not available. Which one of the following is the most appropriate next step in\nmanagement?","options":{"A":"Proceed with the surgery.","B":"Wait until you can find the daughter and obtain consent.","C":"Do not perform the surgery.","D":"Perform the surgery after signatures from two other doctors.","E":"Apply the case to the court for guardianship."},"source_answer":"A","source_explanation":"In emergency situations, when the patient is permanently or temporarily unable to give consent, and there is no carer\nor guardian or next of kin available to obtain consent from, and delaying the treatment will pose risk to patient’s\nhealth, treatment can be provided without consent. This is based on the principle of duty of care and the patient’s\nbest interest, and assuming that the patient’s or his/her carer would consent to treatment if he/she was present.\nHowever, if there is an advanced care directive made in the past by the patients, the instruction contained in that\nmust be followed.\n(Option B) In emergency situations, slightest delay may be associated with increased risks to the patient’s health;\ntherefore, wasting time waiting for the daughter to arrive for consent would be inappropriate.\n(Option C) While this patient is in need for emergency treatment, deferring the surgery is not appropriate.\n(Option D) You are the healthcare professional responsible for the care and health of the patient and no approval\nfrom other doctors is required.\n(Option E) Application of the case to the guardianship court in instances where a patient is in need for emergency\ntreatment is not appropriate, as delay in treatment is against duty of care and the patient’s best interest.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"cbb2224474c418b0e95a5542bcac1cc27fcabcfa","duplicate_group_id":"exact-cbb2224474c4","duplicate_sources":[{"record_id":"8a6c4bf2005bd7831368","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":431,"source_qid":"1191"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.