INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('94c9284eee0961da0568','Amedex 2023.pdf','437','Mixed/Unclassified','A 49-year-old married man is brought to the Emergency Department with internal bleeding from injuries sustained in
a motor vehicle crash. The patient has been stabilized but requires blood transfusion prior to planned emergency
surgery. When he is asked to give consent for the transfusion, he states that blood transfusion is forbidden in his
religion. Which one of the following is the most appropriate next step in management?','{"A":"Assess the patient’s decision-making capacity to refuse the transfusion.","B":"Call the patient’s wife to obtain consent for the transfusion.","C":"Call the Guardianship Court for consent.","D":"Proceed with transfusion against the patient’s wish.","E":"Talk to the patient about blood substitutes and ask him if he would like to consider them."}','A','According to Australian law every competent adult individual has full control over his/her body even if this means
refusing life-saving treatment. There is no exception to this rule if the patient is competent; therefore, the first step
would be assessing the patient’s competency to make decisions. Decision-making capacity includes understanding,
appreciation and reasoning.
Once the patient is proved to be competent, other measures such as transfusing Hemacil® or other intravenous
fluids may be considered and discussed with the patient. 
It should be borne in mind that although parents of an underage individual are required to consent to the
treatment, this will not apply if the treatment is life-saving or limb-saving. In other words, if the patient in the
vignette was a minor, blood transfusion should be performed against the parent’s will.
Guardianship court is consulted when patient lacks competency either due to impaired judgment or suppressed level
of consciousness and there is no advance directives and there is conflict between family members and the treating
physician, or between the family members themselves.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"607","duplicate_group_id":"exact-2f156421f448","duplicate_sources":[{"record_id":"94c9284eee0961da0568","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":437,"source_qid":"607"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"94c9284eee0961da0568","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":437,"source_qid":"607","domain_hint":"Mixed/Unclassified","stem":"A 49-year-old married man is brought to the Emergency Department with internal bleeding from injuries sustained in\na motor vehicle crash. The patient has been stabilized but requires blood transfusion prior to planned emergency\nsurgery. When he is asked to give consent for the transfusion, he states that blood transfusion is forbidden in his\nreligion. Which one of the following is the most appropriate next step in management?","options":{"A":"Assess the patient’s decision-making capacity to refuse the transfusion.","B":"Call the patient’s wife to obtain consent for the transfusion.","C":"Call the Guardianship Court for consent.","D":"Proceed with transfusion against the patient’s wish.","E":"Talk to the patient about blood substitutes and ask him if he would like to consider them."},"source_answer":"A","source_explanation":"According to Australian law every competent adult individual has full control over his/her body even if this means\nrefusing life-saving treatment. There is no exception to this rule if the patient is competent; therefore, the first step\nwould be assessing the patient’s competency to make decisions. Decision-making capacity includes understanding,\nappreciation and reasoning.\nOnce the patient is proved to be competent, other measures such as transfusing Hemacil® or other intravenous\nfluids may be considered and discussed with the patient. \nIt should be borne in mind that although parents of an underage individual are required to consent to the\ntreatment, this will not apply if the treatment is life-saving or limb-saving. In other words, if the patient in the\nvignette was a minor, blood transfusion should be performed against the parent’s will.\nGuardianship court is consulted when patient lacks competency either due to impaired judgment or suppressed level\nof consciousness and there is no advance directives and there is conflict between family members and the treating\nphysician, or between the family members themselves.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"2f156421f448ad1f5cee9bd9596e5cc87d65adb8","duplicate_group_id":"exact-2f156421f448","duplicate_sources":[{"record_id":"94c9284eee0961da0568","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":437,"source_qid":"607"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=e