INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('476f26634b9d9ed3ce0c','Amedex 2023.pdf','443','Mixed/Unclassified','During your shifts, you come to know that one of the interns in your ward has been giving
inappropriate doses of medications to patients at different occasions for the past several weeks.
Which one of the following is the best action to take?','{"A":"Talk to the intern about your concern and his mistake.","B":"Report to the supervisor of intern training.","C":"Tell the ward nurse to help the intern.","D":"Report to Medical Board.","E":"Report to the hospital manager."}','B','Issues related to interns in a hospital or clinic, whether it is impairment, misconduct, or mistakes
are often directly reported to the supervisor of intern training (SIT) or director of clinical training.
One exception is where there is immediate and serious risk to the wellbeing or safety of patients or
other staff, in which case action should be taken immediately. For example, if you witness that an
intern is about to administer an inappropriate dose of the drug you should tell him/her about it
before he/she can put more risk to the patient’s health.
NOTE – It is the responsibility of the SIT or the director of clinical training to notify the relevant
authorities such as AHPRA in case of any notifiable misconduct or impairment.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1389","duplicate_group_id":"exact-aff2a8414b35","duplicate_sources":[{"record_id":"476f26634b9d9ed3ce0c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":443,"source_qid":"1389"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"476f26634b9d9ed3ce0c","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":443,"source_qid":"1389","domain_hint":"Mixed/Unclassified","stem":"During your shifts, you come to know that one of the interns in your ward has been giving\ninappropriate doses of medications to patients at different occasions for the past several weeks.\nWhich one of the following is the best action to take?","options":{"A":"Talk to the intern about your concern and his mistake.","B":"Report to the supervisor of intern training.","C":"Tell the ward nurse to help the intern.","D":"Report to Medical Board.","E":"Report to the hospital manager."},"source_answer":"B","source_explanation":"Issues related to interns in a hospital or clinic, whether it is impairment, misconduct, or mistakes\nare often directly reported to the supervisor of intern training (SIT) or director of clinical training.\nOne exception is where there is immediate and serious risk to the wellbeing or safety of patients or\nother staff, in which case action should be taken immediately. For example, if you witness that an\nintern is about to administer an inappropriate dose of the drug you should tell him/her about it\nbefore he/she can put more risk to the patient’s health.\nNOTE – It is the responsibility of the SIT or the director of clinical training to notify the relevant\nauthorities such as AHPRA in case of any notifiable misconduct or impairment.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["dose","drug"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"aff2a8414b35c646e2e68cdfce8b3bccef2caf8b","duplicate_group_id":"exact-aff2a8414b35","duplicate_sources":[{"record_id":"476f26634b9d9ed3ce0c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":443,"source_qid":"1389"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
