INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('da99ce6153c05547a2fb','Amedex 2023.pdf','446','Mixed/Unclassified','Jane is in your office for her laboratory test results you ordered 15 days ago when you suspected
she may have systemic lupus erythematosus (SLE) based on her history and clinical findings. The
test results confirm your diagnosis. You write a referral letter to a local rheumatologist for
consultation. She wants to know for how long this referral letter is valid. Which one of the following
would be you correct response to her question?','{"A":"Three months from the date of issue.","B":"Three months from the first visit by the specialist.","C":"Six months from the first visit by the specialist.","D":"One year from the date of issue.","E":"One year from the first visit by the specialist."}','E','If supplied by a general practitioner (GP), the law states that a referral is valid for a single course of
treatment for a period of 12 months (one year) after the first service given in accordance with the
referral. Despite this limitation, the referring practitioner can specify an alternative time period such
as three, six, or 18 months or indefinite. Indefinite referrals are not usually made because patients
often have a specific condition requiring a certain amount of time and treatment from specialists.
Note that the referral period begins on the date of the first specialist visit, not on the date the
referral was written. This is frequently misunderstood, including by general practitioners,
specialists and their receptionists.
Other rules to remember are:
Referrals from a specialist are valid for only three months (after the first visit by the practice
the patient has been referred to).
A referral for admitted patients is valid for three months, or the duration of the admission,
whichever is the longer.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1482","duplicate_group_id":"exact-b007c3e75552","duplicate_sources":[{"record_id":"da99ce6153c05547a2fb","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":446,"source_qid":"1482"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"da99ce6153c05547a2fb","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":446,"source_qid":"1482","domain_hint":"Mixed/Unclassified","stem":"Jane is in your office for her laboratory test results you ordered 15 days ago when you suspected\nshe may have systemic lupus erythematosus (SLE) based on her history and clinical findings. The\ntest results confirm your diagnosis. You write a referral letter to a local rheumatologist for\nconsultation. She wants to know for how long this referral letter is valid. Which one of the following\nwould be you correct response to her question?","options":{"A":"Three months from the date of issue.","B":"Three months from the first visit by the specialist.","C":"Six months from the first visit by the specialist.","D":"One year from the date of issue.","E":"One year from the first visit by the specialist."},"source_answer":"E","source_explanation":"If supplied by a general practitioner (GP), the law states that a referral is valid for a single course of\ntreatment for a period of 12 months (one year) after the first service given in accordance with the\nreferral. Despite this limitation, the referring practitioner can specify an alternative time period such\nas three, six, or 18 months or indefinite. Indefinite referrals are not usually made because patients\noften have a specific condition requiring a certain amount of time and treatment from specialists.\nNote that the referral period begins on the date of the first specialist visit, not on the date the\nreferral was written. This is frequently misunderstood, including by general practitioners,\nspecialists and their receptionists.\nOther rules to remember are:\nReferrals from a specialist are valid for only three months (after the first visit by the practice\nthe patient has been referred to).\nA referral for admitted patients is valid for three months, or the duration of the admission,\nwhichever is the longer.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["duration","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"b007c3e75552ef27a82836f9cfd1926633df7ee8","duplicate_group_id":"exact-b007c3e75552","duplicate_sources":[{"record_id":"da99ce6153c05547a2fb","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":446,"source_qid":"1482"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.