INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9a96f75e2ebca1cdf7a1','Amedex 2023.pdf','460','Mixed/Unclassified','An 18-year-old Aboriginal man is brought to the Emergency Department of a local hospital. He is
very agitated, hostile, and aggressive. When approached for care, he becomes even more
distressed and starts yelling at the staff and threatening to kill them if they touch him. Verbal de-
escalation fails to calm him down. After calling the security staff to take over the situation, which
one of the following would be the most appropriate next step in management?','{"A":"Discharge him.","B":"Call the police.","C":"Involuntary admission to the hospital.","D":"Asking for an Aboriginal health worker.","E":"Restrain him."}','D','According to risk management protocol in Australia, calling the security is the most appropriate
step if verbal de-escalating fails. However, the situation with Aboriginals and Torres Strait Islanders
is different. Aboriginal hospital experience can be very stressful for Aboriginals and also
bewildering for health workers.
In such cases, Aboriginal and Torres Strait islander hospital liaison officers (IHLO’s) play an
important role in making rapport and building relationship with Aboriginal patients. Therefore, it is
strongly recommended that prior to any physical restraining or contacting the police, the IHLO or
Aboriginal health worker is contacted to be present and de-escalate the situation.
The main reason for such necessity is the cultural differences and the familiarity of Aboriginal
health workers with the background and sensitivities of this group. For example, while a caring eye
contact is usually perceived as empathy from an aggressive patient, it is unacceptable and
provoking for Aboriginal Australians.
The security staff also must be present in case they are needed but no intervention should take
place as long as possible, and until the Aboriginal health worker takes over.
Other options may be considered after appropriate intervention by and advice from an IHLO or
Aboriginal health worker.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1592","duplicate_group_id":"exact-3adf7aee5378","duplicate_sources":[{"record_id":"9a96f75e2ebca1cdf7a1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":460,"source_qid":"1592"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"9a96f75e2ebca1cdf7a1","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":460,"source_qid":"1592","domain_hint":"Mixed/Unclassified","stem":"An 18-year-old Aboriginal man is brought to the Emergency Department of a local hospital. He is\nvery agitated, hostile, and aggressive. When approached for care, he becomes even more\ndistressed and starts yelling at the staff and threatening to kill them if they touch him. Verbal de-\nescalation fails to calm him down. After calling the security staff to take over the situation, which\none of the following would be the most appropriate next step in management?","options":{"A":"Discharge him.","B":"Call the police.","C":"Involuntary admission to the hospital.","D":"Asking for an Aboriginal health worker.","E":"Restrain him."},"source_answer":"D","source_explanation":"According to risk management protocol in Australia, calling the security is the most appropriate\nstep if verbal de-escalating fails. However, the situation with Aboriginals and Torres Strait Islanders\nis different. Aboriginal hospital experience can be very stressful for Aboriginals and also\nbewildering for health workers.\nIn such cases, Aboriginal and Torres Strait islander hospital liaison officers (IHLO’s) play an\nimportant role in making rapport and building relationship with Aboriginal patients. Therefore, it is\nstrongly recommended that prior to any physical restraining or contacting the police, the IHLO or\nAboriginal health worker is contacted to be present and de-escalate the situation.\nThe main reason for such necessity is the cultural differences and the familiarity of Aboriginal\nhealth workers with the background and sensitivities of this group. For example, while a caring eye\ncontact is usually perceived as empathy from an aggressive patient, it is unacceptable and\nprovoking for Aboriginal Australians.\nThe security staff also must be present in case they are needed but no intervention should take\nplace as long as possible, and until the Aboriginal health worker takes over.\nOther options may be considered after appropriate intervention by and advice from an IHLO or\nAboriginal health worker.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"3adf7aee53786dc23fd84e9299deb842aaa32615","duplicate_group_id":"exact-3adf7aee5378","duplicate_sources":[{"record_id":"9a96f75e2ebca1cdf7a1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":460,"source_qid":"1592"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=ex