INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('89cc034ab3b6b0194fc4','Amedex 2023.pdf','465','Mixed/Unclassified','Mary and John, an infertile couple, finally manage to conceive IVF. They are in your office today for
prenatal care and also to discuss whether they can sell the leftover eggs, sperms, and embryos.
Which one of the following is correct regarding selling sperms, eggs, or embryos in Australia?','{"A":"It is illegal to sell the embryos, but eggs and sperms can be sold.","B":"It is legal to sell the eggs, sperms, and embryos.","C":"It is illegal to sell sperms, egg, or embryos.","D":"It is illegal to sell eggs and embryos but legal to sell sperms.","E":"It is illegal to sell sperms, but embryos and eggs can be sold."}','C','In Australia, buying or selling organ tissues of any kind, including eggs, sperms, and embryos is
illegal. Donations are allowed (no profit involved). However, the donor can request reimbursement
for out-of-pocket expenses such as times away from work, travel expenses, etc. This is different
from the United States where it is legal to sell or by sperms and eggs, but trading embryos is illegal.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1684","duplicate_group_id":"exact-c3642b03294d","duplicate_sources":[{"record_id":"89cc034ab3b6b0194fc4","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":465,"source_qid":"1684"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"89cc034ab3b6b0194fc4","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":465,"source_qid":"1684","domain_hint":"Mixed/Unclassified","stem":"Mary and John, an infertile couple, finally manage to conceive IVF. They are in your office today for\nprenatal care and also to discuss whether they can sell the leftover eggs, sperms, and embryos.\nWhich one of the following is correct regarding selling sperms, eggs, or embryos in Australia?","options":{"A":"It is illegal to sell the embryos, but eggs and sperms can be sold.","B":"It is legal to sell the eggs, sperms, and embryos.","C":"It is illegal to sell sperms, egg, or embryos.","D":"It is illegal to sell eggs and embryos but legal to sell sperms.","E":"It is illegal to sell sperms, but embryos and eggs can be sold."},"source_answer":"C","source_explanation":"In Australia, buying or selling organ tissues of any kind, including eggs, sperms, and embryos is\nillegal. Donations are allowed (no profit involved). However, the donor can request reimbursement\nfor out-of-pocket expenses such as times away from work, travel expenses, etc. This is different\nfrom the United States where it is legal to sell or by sperms and egg