INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('577424f3a02ac3b1b41f','Amedex 2023.pdf','477','Mixed/Unclassified','A 75-year-old man is brought to the hospital with reduced level of consciousness. CT scan of the head shows
epidural hematoma requiring non-urgent surgery. You are unable to discuss the procedure with the patient due to his
decreased level of consciousness. His spouse and the eldest son are present. His spouse says that her husband
never wanted to come to the hospital and would never want to be resuscitated or have any surgery on him. His son
requests you to do everything possible to save his father’s life. Which one of the following is the most appropriate
action?','{"A":"Listen to his son.","B":"Arrange a family meeting to reach a consensus.","C":"Apply for guardianship.","D":"Listen to his wife.","E":"Request the medical superintendent to assess the patient capacity."}','D','If a person cannot give consent for their own treatment and there is no advance health directive present, a health
practitioner should obtain consent from the “person responsible”. In this situation, patient’ spouse can consent for
the patient’s future treatment. A spouse’s opinion is considered more valid and appropriate than that of sons or
daughters; therefore, the directives should be obtained from the wife. One other important step is trying to find out
whether the patient was competent or not when he expressed such wishes.
In instances where no advance health directive or a spouse, family members, or carer is present, a medical
superintendent or authorized medical officer can decide for life-saving emergency surgery if the patient is
incompetent to make a decision.
Application to Guardianship is required for all those patients who lack the capacity to decide about their treatment;
however it usually takes few days.
Under the Guardianship Act 1987, a ''person responsible'' can make decisions about most medical or dental
treatments.
A ''person responsible'' is, in order of priority:
(1) - The legally appointed guardian of the person (including enduring guardian) with the function of consenting to
medical/dental treatment
If there is not one then
(2) - Their spouse or de facto spouse or same sex partner, or if there is no spouse or de facto spouse or same sex
partner
If there is not one then
(3) - Their unpaid carer
If there is not one then
(4) - The patient’s nearest relative over the age of 18 year, which means (in order of preference):
Son or daughter','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-7f6d3537b7aa","duplicate_sources":[{"record_id":"577424f3a02ac3b1b41f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":477,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"577424f3a02ac3b1b41f","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":477,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 75-year-old man is brought to the hospital with reduced level of consciousness. CT scan of the head shows\nepidural hematoma requiring non-urgent surgery. You are unable to discuss the procedure with the patient due to his\ndecreased level of consciousness. His spouse and the eldest son are present. His spouse says that her husband\nnever wanted to come to the hospital and would never want to be resuscitated or have any surgery on him. His son\nrequests you to do everything possible to save his father’s life. Which one of the following is the most appropriate\naction?","options":{"A":"Listen to his son.","B":"Arrange a family meeting to reach a consensus.","C":"Apply for guardianship.","D":"Listen to his wife.","E":"Request the medical superintendent to assess the patient capacity."},"source_answer":"D","source_explanation":"If a person cannot give consent for their own treatment and there is no advance health directive present, a health\npractitioner should obtain consent from the “person responsible”. In this situation, patient’ spouse can consent for\nthe patient’s future treatment. A spouse’s opinion is considered more valid and appropriate than that of sons or\ndaughters; therefore, the directives should be obtained from the wife. One other important step is trying to find out\nwhether the patient was competent or not when he expressed such wishes.\nIn instances where no advance health directive or a spouse, family members, or carer is present, a medical\nsuperintendent or authorized medical officer can decide for life-saving emergency surgery if the patient is\nincompetent to make a decision.\nApplication to Guardianship is required for all those patients who lack the capacity to decide about their treatment;\nhowever it usually takes few days.\nUnder the Guardianship Act 1987, a ''person responsible'' can make decisions about most medical or dental\ntreatments.\nA ''person responsible'' is, in order of priority:\n(1) - The legally appointed guardian of the person (including enduring guardian) with the function of consenting to\nmedical/dental treatment\nIf there is not one then\n(2) - Their spouse or de facto spouse or same sex partner, or if there is no spouse or de facto spouse or same sex\npartner\nIf there is not one then\n(3) - Their unpaid carer\nIf there is not one then\n(4) - The patient’s nearest relative over the age of 18 year, which means (in order of preference):\nSon or daughter","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"7f6d3537b7aa930907e81d4598e04ebd8c2afcc2","duplicate_group_id":"exact-7f6d3537b7aa","duplicate_sources":[{"record_id":"577424f3a02ac3b1b41f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":477,"source_