INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('74e5eddbe905fcb5c0eb','Amedex 2023.pdf','498','Mixed/Unclassified','A mother of two children aged 9 and 18 years is concerned about her children developing hemochromatosis, as his husband has recently been diagnoses with the disease. Regarding screening for hemochromatosis, which one of the following is the
next best in management?','{"A":"Screen the 9-year-old boy.","B":"Screen the 18-year-old boy.","C":"Screen both children.","D":"Screen the mother.","E":"No screening is needed as the disease becomes clinically evident between 30-60 years."}','D','The gene involved in hereditary hemochromatosis (HH) is called the HFE gene. Mutations in the HFE gene can lead to impaired regulation of iron storage and clinical manifestations of hemochromatosis. There are two types of mutation in HFE gene:
C282Y and H63D.
Terminology
Those with only one copy of the mutated HFE (either C282Y or H63D) gene are called heterozygote.
Those with two copies of C282Y mutation are called ‘homozygote’. Since those with two copies of H63D mutation never develop clinical hemochromatosis, homozygote, refers to a person with both copies of HFE with C282Y mutation
only.
Those with one copy of HFE gene with C282Y mutation and the other with H63D mutation are called ‘compound heterozygote’. These individuals are often asymptomatic and if symptoms are present they are mild.
About 90% of people of Northern European ancestry with symptoms of HH have the C282Y mutation in both copies of their HFE gene (homozygote). Two percent are compound heterozygote (see above).
Since HH follows an autosomal recessive pattern of inheritance, there is often no family history, or affected family members may appear to be scattered in generations. If both parents heterozygous (carriers for a mutation in the HFE gene), there is a
25% chance for their children to be affected and genetically predisposed to HH.
Current guidelines advise that first-degree and second-degree relatives of individuals, who have HH or are homozygous for the C282Y gene mutation, are tested with iron studies and the HFE gene test. Based on this recommendation, both children
should be considered for testing; however, in this case testing the mother would be more convenient and reasonable. If she does not have a faulty HFE gene, no further testing of the children would be indicated, because even if the father is
homozygote, the children would only be carriers in the worst case scenario.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"474","duplicate_group_id":"exact-06e4ee2c203c","duplicate_sources":[{"record_id":"74e5eddbe905fcb5c0eb","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":498,"source_qid":"474"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"74e5eddbe905fcb5c0eb","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":498,"source_qid":"474","domain_hint":"Mixed/Unclassified","stem":"A mother of two children aged 9 and 18 years is concerned about her children developing hemochromatosis, as his husband has recently been diagnoses with the disease. Regarding screening for hemochromatosis, which one of the following is the\nnext best in management?","options":{"A":"Screen the 9-year-old boy.","B":"Screen the 18-year-old boy.","C":"Screen both children.","D":"Screen the mother.","E":"No screening is needed as the disease becomes clinically evident between 30-60 years."},"source_answer":"D","source_explanation":"The gene involved in hereditary hemochromatosis (HH) is called the HFE gene. Mutations in the HFE gene can lead to impaired regulation of iron storage and clinical manifestations of hemochromatosis. There are two types of mutation in HFE gene:\nC282Y and H63D.\nTerminology\nThose with only one copy of the mutated HFE (either C282Y or H63D) gene are called heterozygote.\nThose with two copies of C282Y mutation are called ‘homozygote’. Since those with two copies of H63D mutation never develop clinical hemochromatosis, homozygote, refers to a person with both copies of HFE with C282Y mutation\nonly.\nThose with one copy of HFE gene with C282Y mutation and the other with H63D mutation are called ‘compound heterozygote’. These individuals are often asymptomatic and if symptoms are present they are mild.\nAbout 90% of people of Northern European ancestry with symptoms of HH have the C282Y mutation in both copies of their HFE gene (homozygote). Two percent are compound heterozygote (see above).\nSince HH follows an autosomal recessive pattern of inheritance, there is often no family history, or affected family members may appear to be scattered in generations. If both parents heterozygous (carriers for a mutation in the HFE gene), there is a\n25% chance for their children to be affected and genetically predisposed to HH.\nCurrent guidelines advise that first-degree and second-degree relatives of individuals, who have HH or are homozygous for the C282Y gene mutation, are tested with iron studies and the HFE gene test. Based on this recommendation, both children\nshould be considered for testing; however, in this case testing the mother would be more convenient and reasonable. If she does not have a faulty HFE gene, no further testing of the children would be indicated, because even if the father is\nhomozygote, the children would only be carriers in the worst case scenario.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","guideline","management","screen","screening"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"06e4ee2c203c18b75975ad6d1b681cce170a62aa","duplicate_group_id":"exact-06e4ee2c203c","duplicate_sources":[{"record_id":"74e5eddbe905fcb5c0eb","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_rel