INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d6fd735244b24e030e34','Amedex 2023.pdf','499','Mixed/Unclassified','The photograph is one of a barium swallow series performed in a 78-year-old man. He has presented with symptoms of 12 months duration. Which one of the following could be the most likely presenting symptom?','{"A":"Recurrent chest infection.","B":"Progressive weight loss.","C":"Retrosternal burning sensation.","D":"Gurgling in the neck.","E":"Food regurgitation."}','E','The photograph shows a pocket of contrast material at the root of the neck, as well as the contrast in the esophagus characteristic of retropharyngeal pouch (Zenker’s diverticulum). The condition is most commonly found in the elderly population.
Patients with Zenker’s diverticulum usually have dysphagia because the primary problem is an overactive upper esophageal sphincter, which fails to relax. Despite long-standing dysphagia, patients usually do not have significant weight loss.
When the pharyngeal pouch becomes large enough to retain contents such as mucus, pills, sputum and food, the patient may complain of pulmonary aspiration and recurrent chest infections, foul-smell breath, gurgling in the throat, appearance of a
mass in the neck, or regurgitation of food into the mouth.
Of these symptoms, however, food regurgitation is the most distressing symptoms for which medical attention is usually sought..
Retrosternal burning sensation is a characteristic feature of gastro-esophageal reflux disease (GERD) and is not an associated symptom in Zenker’s diverticulum.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"476","duplicate_group_id":"exact-a31dd533ee7a","duplicate_sources":[{"record_id":"d6fd735244b24e030e34","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":499,"source_qid":"476"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"d6fd735244b24e030e34","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":499,"source_qid":"476","domain_hint":"Mixed/Unclassified","stem":"The photograph is one of a barium swallow series performed in a 78-year-old man. He has presented with symptoms of 12 months duration. Which one of the following could be the most likely presenting symptom?","options":{"A":"Recurrent chest infection.","B":"Progressive weight loss.","C":"Retrosternal burning sensation.","D":"Gurgling in the neck.","E":"Food regurgitation."},"source_answer":"E","source_explanation":"The photograph shows a pocket of contrast material at the root of the neck, as well as the contrast in the esophagus characteristic of retropharyngeal pouch (Zenker’s diverticulum). The condition is most commonly found in the elderly population.\nPatients with Zenker’s diverticulum usually have dysphagia because the primary problem is an overactive upper esophageal sphincter, which fails to relax. Despite long-standing dysphagia, patients usually do not have significant weight loss.\nWhen the pharyngeal pouch becomes large enough to retain contents such as mucus, pills, sputum and food, the patient may complain of pulmonary aspiration and recurrent chest infections, foul-smell breath, gurgling in the throat, appearance of a\nmass in the neck, or regurgitation of food into the mouth.\nOf these symptoms, however, food regurgitation is the most distressing symptoms for which medical attention is usually sought..\nRetrosternal burning sensation is a characteristic feature of gastro-esophageal reflux disease (GERD) and is not an associated symptom in Zenker’s diverticulum.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","duration"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a31dd533ee7a3e8d6a850db303dc1bb21fbd0758","duplicate_group_id":"exact-a31dd533ee7a","duplicate_sources":[{"record_id":"d6fd735244b24e030e34","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":499,"source_qid":"476"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
