INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a94ed90bb3239a4a99e3','Amedex 2023.pdf','500','Mixed/Unclassified','A 69-year-old woman is diagnosed with carcinoma of the cecum. Which one of the following is more likely to have been her initial presenting symptoms?','{"A":"Right iliac fossa (RIF) mass.","B":"Altered bowel habit.","C":"Weakness and fatigue.","D":"Melena.","E":"Bright rectal bleeding."}','C','Colorectal cancers may present with a wide variety of symptoms. The presenting symptoms, to a great extent, depends on the location of the tumor.
A change in bowel habits is a less common presenting symptom for right-sided tumors because feces is liquid in the proximal colon and the lumen caliber is larger. Right-sided tumors present with anemia and fatigue due to chronic blood loss, while
tumors of the left side are associated with altered bowel habits and rectal bleeding.
(Option A) If a right-sided tumor is large enough, a right iliac fossa mass may be palpated. But a tumor that large has already caused significant symptoms for which the patient has already sought medical attention.
(Option B) Altered bowel habit is more commonly seen in left-sided colon cancers, including rectal tumors.
(Option D) Melena is associated with upper gastrointestinal (GI) bleeding with prolonged passage time of the blood through the gastrointestinal tract. Colorectal tumors are very unlikely to cause melena.
(Option E) Rectal bleeding is often caused by a rectal cancer or more distal left-sided colon cancers.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"477","duplicate_group_id":"exact-1ed1a92cf718","duplicate_sources":[{"record_id":"a94ed90bb3239a4a99e3","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":500,"source_qid":"477"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"a94ed90bb3239a4a99e3","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":500,"source_qid":"477","domain_hint":"Mixed/Unclassified","stem":"A 69-year-old woman is diagnosed with carcinoma of the cecum. Which one of the following is more likely to have been her initial presenting symptoms?","options":{"A":"Right iliac fossa (RIF) mass.","B":"Altered bowel habit.","C":"Weakness and fatigue.","D":"Melena.","E":"Bright rectal bleeding."},"source_answer":"C","source_explanation":"Colorectal cancers may present with a wide variety of symptoms. The presenting symptoms, to a great extent, depends on the location of the tumor.\nA change in bowel habits is a less common presenting symptom for right-sided tumors because feces is liquid in the proximal colon and the lumen caliber is larger. Right-sided tumors present with anemia and fatigue due to chronic blood loss, while\ntumors of the left side are associated with altered bowel habits and rectal bleeding.\n(Option A) If a right-sided tumor is large enough, a right iliac fossa mass may be palpated. But a tumor that large has already caused significant symptoms for which the patient has already sought medical attention.\n(Option B) Altered bowel habit is more commonly seen in left-sided colon cancers, including rectal tumors.\n(Option D) Melena is associated with upper gastrointestinal (GI) bleeding with prolonged passage time of the blood through the gastrointestinal tract. Colorectal tumors are very unlikely to cause melena.\n(Option E) Rectal bleeding is often caused by a rectal cancer or more distal left-sided colon cancers.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1ed1a92cf718613572219627ff7f8623dde7d238","duplicate_group_id":"exact-1ed1a92cf718","duplicate_sources":[{"record_id":"a94ed90bb3239a4a99e3","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":500,"source_qid":"477"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
