INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('a94ed90bb3239a4a99e3','src-v294-687f312c','477','500','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 69-year-old woman is diagnosed with carcinoma of the cecum. Which one of the following is more likely to have been her initial presenting symptoms?',NULL,'C','Colorectal cancers may present with a wide variety of symptoms. The presenting symptoms, to a great extent, depends on the location of the tumor.
A change in bowel habits is a less common presenting symptom for right-sided tumors because feces is liquid in the proximal colon and the lumen caliber is larger. Right-sided tumors present with anemia and fatigue due to chronic blood loss, while
tumors of the left side are associated with altered bowel habits and rectal bleeding.
(Option A) If a right-sided tumor is large enough, a right iliac fossa mass may be palpated. But a tumor that large has already caused significant symptoms for which the patient has already sought medical attention.
(Option B) Altered bowel habit is more commonly seen in left-sided colon cancers, including rectal tumors.
(Option D) Melena is associated with upper gastrointestinal (GI) bleeding with prolonged passage time of the blood through the gastrointestinal tract. Colorectal tumors are very unlikely to cause melena.
(Option E) Rectal bleeding is often caused by a rectal cancer or more distal left-sided colon cancers.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"477","duplicate_group_id":"exact-1ed1a92cf718","duplicate_sources":[{"record_id":"a94ed90bb3239a4a99e3","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":500,"source_qid":"477"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
