INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f1dcc47b138d047c2672','Amedex 2023.pdf','503','Mixed/Unclassified','You are one of the senior residents in surgery. You are called to see Mr. Kingsley, a 67-year-old man, who has just been diagnosed with acute cholangitis. Which one of the following statements is not correct regarding the management of acute
cholangitis?','{"A":"Plan for immediate decompression if the patient does not respond to initial measures.","B":"Plan for biliary decompression on semi-urgent basis (<72 hours) if the patient is responding to initial resuscitation.","C":"Plan for urgent decompression (within 24-48hrs) if the patient is older than 70 years.","D":"The most appropriate method of biliary decompression is ERCP, sphincterectomy and stenting.","E":"Initial aggressive resuscitation and antibiotics usually fail to get good response in majority of cases."}','E','Acute ascending cholangitis is initially managed with aggressive fluid resuscitation and intravenous antibiotics followed by biliary decompression.
Since the infectious organisms responsible for acute ascending cholangitis are enteric gram negative bacteria, the selected antibiotic of choice should provide appropriate coverage against these germs.
All patients with ascending cholangitis require biliary drainage. In about 85-90% of patients, there is respond to medical therapy. In this group decompression may be performed semi-electively during the same admission (and ideally within 72 hours);
however for the following patients urgent decompression may be considered:
Patients older than 70 years
Patients with diabetes
Patients with other comorbid conditions
Approximately 10% to 15% of patients (not the majority) fail to respond within 12 to 24 hours or deteriorate after initial medical therapy and need urgent biliary decompression. Delay to do so increases the chance of an adverse outcomes.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"480","duplicate_group_id":"exact-a759747331ed","duplicate_sources":[{"record_id":"f1dcc47b138d047c2672","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":503,"source_qid":"480"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"f1dcc47b138d047c2672","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":503,"source_qid":"480","domain_hint":"Mixed/Unclassified","stem":"You are one of the senior residents in surgery. You are called to see Mr. Kingsley, a 67-year-old man, who has just been diagnosed with acute cholangitis. Which one of the following statements is not correct regarding the management of acute\ncholangitis?","options":{"A":"Plan for immediate decompression if the patient does not respond to initial measures.","B":"Plan for biliary decompression on semi-urgent basis (<72 hours) if the patient is responding to initial resuscitation.","C":"Plan for urgent decompression (within 24-48hrs) if the patient is older than 70 years.","D":"The most appropriate method of biliary decompression is ERCP, sphincterectomy and stenting.","E":"Initial aggressive resuscitation and antibiotics usually fail to get good response in majority of cases."},"source_answer":"E","source_explanation":"Acute ascending cholangitis is initially managed with aggressive fluid resuscitation and intravenous antibiotics followed by biliary decompression.\nSince the infectious organisms responsible for acute ascending cholangitis are enteric gram negative bacteria, the selected antibiotic of choice should provide appropriate coverage against these germs.\nAll patients with ascending cholangitis require biliary drainage. In about 85-90% of patients, there is respond to medical therapy. In this group decompression may be performed semi-electively during the same admission (and ideally within 72 hours);\nhowever for the following patients urgent decompression may be considered:\nPatients older than 70 years\nPatients with diabetes\nPatients with other comorbid conditions\nApproximately 10% to 15% of patients (not the majority) fail to respond within 12 to 24 hours or deteriorate after initial medical therapy and need urgent biliary decompression. Delay to do so increases the chance of an adverse outcomes.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","diabetes","management","resuscitation","therapy"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a759747331ed45887f8b229df420ade44657a51c","duplicate_group_id":"exact-a759747331ed","duplicate_sources":[{"record_id":"f1dcc47b138d047c2672","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":503,"source_qid":"480"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
