INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('f1dcc47b138d047c2672','src-v294-687f312c','480','503','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','You are one of the senior residents in surgery. You are called to see Mr. Kingsley, a 67-year-old man, who has just been diagnosed with acute cholangitis. Which one of the following statements is not correct regarding the management of acute
cholangitis?',NULL,'E','Acute ascending cholangitis is initially managed with aggressive fluid resuscitation and intravenous antibiotics followed by biliary decompression.
Since the infectious organisms responsible for acute ascending cholangitis are enteric gram negative bacteria, the selected antibiotic of choice should provide appropriate coverage against these germs.
All patients with ascending cholangitis require biliary drainage. In about 85-90% of patients, there is respond to medical therapy. In this group decompression may be performed semi-electively during the same admission (and ideally within 72 hours);
however for the following patients urgent decompression may be considered:
Patients older than 70 years
Patients with diabetes
Patients with other comorbid conditions
Approximately 10% to 15% of patients (not the majority) fail to respond within 12 to 24 hours or deteriorate after initial medical therapy and need urgent biliary decompression. Delay to do so increases the chance of an adverse outcomes.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"480","duplicate_group_id":"exact-a759747331ed","duplicate_sources":[{"record_id":"f1dcc47b138d047c2672","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":503,"source_qid":"480"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
