INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('9dab82b89bfd60377300','Amedex 2023.pdf','508','Mixed/Unclassified','A 42-year-old man is admitted with a hematemesis. On examination she has a blood pressure of 95/60 mmHg and a pulse rate of 104 bpm. He has yellowish sclerae, scratch marks and bruises on his arms. Several spider nevi are noted on his chest
and abdomen. His abdomen is distended and soft with evidence of shifting dullness. Dilated veins are easily visible in the subcutaneous tissue and the liver is palpable two finger-breadths below the costal margin. Which one of the following could be
the most likely underlying cause of his problem?','{"A":"Alcoholic liver disease.","B":"Biliary cirrhosis.","C":"Schistosomiasis.","D":"Budd-Chiari syndrome.","E":"Hepatitis C cirrhosis."}','A','Upper gastrointestinal bleeding may have different causes, but I this man having the clinical features of liver disease and cirrhosis, bleeding from esophageal varices would be the most likely cause of bleeding. Cirrhosis results in portal vein
hypertension.
When the portal vein is obstructed, shunting between the portal vein an systemic veins start to develop. This shunts lead to dilated veins around the umbilicus (caput medusa), in the lower gastrointestinal tract (hemorrhoids), or in the upper
gastrointestinal tract (esophageal varices).
In Australia alcoholic liver disease is the most common cause of chronic liver disease and cirrhosis, followed by hepatitis C infection.
Biliary cirrhosis, schistosomiasis, and Budd-Chiari syndrome can all potentially lead to liver cirrhosis, but are much less common than alcoholic liver disease.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"485","duplicate_group_id":"exact-0eeb7a14adc5","duplicate_sources":[{"record_id":"9dab82b89bfd60377300","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":508,"source_qid":"485"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"9dab82b89bfd60377300","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":508,"source_qid":"485","domain_hint":"Mixed/Unclassified","stem":"A 42-year-old man is admitted with a hematemesis. On examination she has a blood pressure of 95/60 mmHg and a pulse rate of 104 bpm. He has yellowish sclerae, scratch marks and bruises on his arms. Several spider nevi are noted on his chest\nand abdomen. His abdomen is distended and soft with evidence of shifting dullness. Dilated veins are easily visible in the subcutaneous tissue and the liver is palpable two finger-breadths below the costal margin. Which one of the following could be\nthe most likely underlying cause of his problem?","options":{"A":"Alcoholic liver disease.","B":"Biliary cirrhosis.","C":"Schistosomiasis.","D":"Budd-Chiari syndrome.","E":"Hepatitis C cirrhosis."},"source_answer":"A","source_explanation":"Upper gastrointestinal bleeding may have different causes, but I this man having the clinical features of liver disease and cirrhosis, bleeding from esophageal varices would be the most likely cause of bleeding. Cirrhosis results in portal vein\nhypertension.\nWhen the portal vein is obstructed, shunting between the portal vein an systemic veins start to develop. This shunts lead to dilated veins around the umbilicus (caput medusa), in the lower gastrointestinal tract (hemorrhoids), or in the upper\ngastrointestinal tract (esophageal varices).\nIn Australia alcoholic liver disease is the most common cause of chronic liver disease and cirrhosis, followed by hepatitis C infection.\nBiliary cirrhosis, schistosomiasis, and Budd-Chiari syndrome can all potentially lead to liver cirrhosis, but are much less common than alcoholic liver disease.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","hypertension"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"0eeb7a14adc5b4ee4c96e7b039ffa64e718a0efd","duplicate_group_id":"exact-0eeb7a14adc5","duplicate_sources":[{"record_id":"9dab82b89bfd60377300","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":508,"source_qid":"485"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.acti