INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('05f2dc12fb656b13e46f','Amedex 2023.pdf','511','Mixed/Unclassified','You are about to perform a femoral venepuncture and you should take precaution not to damage the adjacent structures. Which one of the following is the order of structures in the groin under the inguinal ligament from medial to lateral?','{"A":"Lacunar ligament, femoral artery, femoral vein, femoral nerve.","B":"Lacunar ligament, femoral vein, femoral nerve, femoral artery.","C":"Lacunar ligament, femoral vein, femoral artery, femoral nerve.","D":"Femoral vein, femoral artery, femoral nerve, lacunar ligament.","E":"Femoral vein. Femoral artery, lacunar ligament, femoral nerve."}','C','Femoral triangle consists of three borders:
Upper border: inguinal ligament
Medial border: lateral border of adductor longus
Lateral border: medial border of sartorius
Femoral trinagle and its contents 
The contents of the femoral triangle from medial to lateral are:
1. Lacunar ligament and deep femoral lymph nodes
2. Femoral vein
3. Femoral artery
4. Femoral nerve
Remember LEVAN: Lymph node chain / lacunar ligament, Empty space, Vein, Artery and Nerve for the order of contents from medial to lateral.
The lacunar ligament is a ligament in the inguinal region that connects the inguinal ligament to the pectineal ligament near the point where they both insert on the pubic tubercle. This ligament comprises the medial border of the femoral canal.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-09c60dd674e4","duplicate_sources":[{"record_id":"05f2dc12fb656b13e46f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":511,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"05f2dc12fb656b13e46f","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":511,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"You are about to perform a femoral venepuncture and you should take precaution not to damage the adjacent structures. Which one of the following is the order of structures in the groin under the inguinal ligament from medial to lateral?","options":{"A":"Lacunar ligament, femoral artery, femoral vein, femoral nerve.","B":"Lacunar ligament, femoral vein, femoral nerve, femoral artery.","C":"Lacunar ligament, femoral vein, femoral artery, femoral nerve.","D":"Femoral vein, femoral artery, femoral nerve, lacunar ligament.","E":"Femoral vein. Femoral artery, lacunar ligament, femoral nerve."},"source_answer":"C","source_explanation":"Femoral triangle consists of three borders:\nUpper border: inguinal ligament\nMedial border: lateral border of adductor longus\nLateral border: medial border of sartorius\nFemoral trinagle and its contents \nThe contents of the femoral triangle from medial to lateral are:\n1. Lacunar ligament and deep femoral lymph nodes\n2. Femoral vein\n3. Femoral artery\n4. Femoral nerve\nRemember LEVAN: Lymph node chain / lacunar ligament, Empty space, Vein, Artery and Nerve for the order of contents from medial to lateral.\nThe lacunar ligament is a ligament in the inguinal region that connects the inguinal ligament to the pectineal ligament near the point where they both insert on the pubic tubercle. This ligament comprises the medial border of the femoral canal.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"09c60dd674e45a09b264ce5fc00ddbb035c5e051","duplicate_group_id":"exact-09c60dd674e4","duplicate_sources":[{"record_id":"05f2dc12fb656b13e46f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":511,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
