INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('357d1bea7bdd3785a96f','Amedex 2023.pdf','541','Mixed/Unclassified','During endoscopic evaluation of a 65-year-old man for dyspepsia, he is found to have an abnormal-appearing patch of mucosa in the distal part of his esophagus. Biopsy result is significant for Barrett''s esophagus and metaplasia. Which one of the
following is correct regarding his condition?','{"A":"He shoudl be monitored every 2-3 years by endoscopy and biopsy.","B":"He should be monitored by endoscopy every third month.","C":"There is 70-80% risk of progression to adenocarcinoma.","D":"Hiatus hernia has no association with Barrett’s esophagus.","E":"Barrett''s esophaus is an indication of urgent surgical intervention."}','A','With metaplasia present in this patient, surveillance with endoscopy and biopsy should be performed every 2-3 years. Other options are incorrect.
Barrett’s esophagus is a condition in which metaplastic columnar epithelium replaces the stratified squamous epithelium of the distal esophagus. The metaplastic epithelium is acquired as a consequence of chronic gastro-esophageal reflux disease
(GERD). Hiatus hernia predisposes to GERD and indirectly to development Barrett’s esophagus.
Barrett’s esophagus is a premalignant condition with a 40- to 125-fold increase in the incidence of adenocarcinoma of the lower esophagus; however, the absolute risk relatively small and approximately 0.5% per year.
Every patient with the alarming symptoms of weight loss, anemia, heme-positive stool, and dysphagia, or GERD for more than 5 years should undergo endoscopy and biopsy. Further management depends on the histological findings and is
summarized in the following table:
Endoscopic Findings
Management
Barrett’s esophagus (metaplasia)
Endoscopy every 2-3 years for lesions ≥ 3cm and every 3-5 years for lesions <3 cm.
Low-grade dysplasia
Repeat endoscopy 6 months.
High grade dysplasia
Distal esophagetomy.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"698","duplicate_group_id":"exact-48f1cae54398","duplicate_sources":[{"record_id":"357d1bea7bdd3785a96f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":541,"source_qid":"698"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"357d1bea7bdd3785a96f","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":541,"source_qid":"698","domain_hint":"Mixed/Unclassified","stem":"During endoscopic evaluation of a 65-year-old man for dyspepsia, he is found to have an abnormal-appearing patch of mucosa in the distal part of his esophagus. Biopsy result is significant for Barrett''s esophagus and metaplasia. Which one of the\nfollowing is correct regarding his condition?","options":{"A":"He shoudl be monitored every 2-3 years by endoscopy and biopsy.","B":"He should be monitored by endoscopy every third month.","C":"There is 70-80% risk of progression to adenocarcinoma.","D":"Hiatus hernia has no association with Barrett’s esophagus.","E":"Barrett''s esophaus is an indication of urgent surgical intervention."},"source_answer":"A","source_explanation":"With metaplasia present in this patient, surveillance with endoscopy and biopsy should be performed every 2-3 years. Other options are incorrect.\nBarrett’s esophagus is a condition in which metaplastic columnar epithelium replaces the stratified squamous epithelium of the distal esophagus. The metaplastic epithelium is acquired as a consequence of chronic gastro-esophageal reflux disease\n(GERD). Hiatus hernia predisposes to GERD and indirectly to development Barrett’s esophagus.\nBarrett’s esophagus is a premalignant condition with a 40- to 125-fold increase in the incidence of adenocarcinoma of the lower esophagus; however, the absolute risk relatively small and approximately 0.5% per year.\nEvery patient with the alarming symptoms of weight loss, anemia, heme-positive stool, and dysphagia, or GERD for more than 5 years should undergo endoscopy and biopsy. Further management depends on the histological findings and is\nsummarized in the following table:\nEndoscopic Findings\nManagement\nBarrett’s esophagus (metaplasia)\nEndoscopy every 2-3 years for lesions ≥ 3cm and every 3-5 years for lesions <3 cm.\nLow-grade dysplasia\nRepeat endoscopy 6 months.\nHigh grade dysplasia\nDistal esophagetomy.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"48f1cae5439880ea7cf511046ff4c3cf64fd1e63","duplicate_group_id":"exact-48f1cae54398","duplicate_sources":[{"record_id":"357d1bea7bdd3785a96f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":541,"source_qid":"698"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.curr