INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('fd8f4067e18fe4070ccd','Amedex 2023.pdf','550','Mixed/Unclassified','A 56-year-old man presents to your practice with complaint of fresh rectal bleeding covering his stool. He has long-standing history of constipation. He mentions no pain on defecation. Which one of the following can be the most likely cause?','{"A":"Colorectal cancer.","B":"External hemorrhoid.","C":"Internal hemorrhoid.","D":"Anorectal fistula.","E":"Anal fissure."}','C','Fresh blood covering the stool in the background history of prolonged constipation is most likely caused by internal hemorrhoid.
Typical pattern of rectal bleeding in internal hemorrhoids is usually associated with a bowel movement. Bright-red blood typically coats the stool at the end of defecation. Blood may also drip into the toilet bowl or stain toilet paper. Hemorrhoidal
bleeding is almost always painless, and painful defecation prompts investigation for other causes such as anorectal fissures.
Although the pattern of rectal bleeding in this man is more likely to have been caused by hemorrhoids, overt or occult rectal bleeding should not be merely attributed to hemorrhoids until other less common but more serious causes of rectal bleeding
have been excluded by endoscopic testing. Flexible sigmoidoscopy or anoscopy in low-risk younger patients or colonoscopy in most other patients establishes the diagnosis of hemorrhoids, and excludes other causes of bleeding such as colitis,
tumors, polyps, or vascular malformations.
(Option A) Presence of rectal bleeding in this patient should also raise suspicion against colorectal cancer. However, this diagnosis is less likely because firstly, there are no other suggestive findings such as weight loss, altering bowel habits, etc. and
secondly, hemorrhoids are more common than cancers statistically.
(Options B and E) External hemorrhoid and anal fissure are associated with significant anal pain and are very unlikely to be the diagnosis in this patient who has no pain on defecation.
(Option D) Anorectal fistulae are associated with soiling rather than rectal bleeding. It is unlikely that painless fresh rectal bleeding is the only presentation of anorectal fistulae.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"901","duplicate_group_id":"exact-b311c5c5dab5","duplicate_sources":[{"record_id":"fd8f4067e18fe4070ccd","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":550,"source_qid":"901"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"fd8f4067e18fe4070ccd","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":550,"source_qid":"901","domain_hint":"Mixed/Unclassified","stem":"A 56-year-old man presents to your practice with complaint of fresh rectal bleeding covering his stool. He has long-standing history of constipation. He mentions no pain on defecation. Which one of the following can be the most likely cause?","options":{"A":"Colorectal cancer.","B":"External hemorrhoid.","C":"Internal hemorrhoid.","D":"Anorectal fistula.","E":"Anal fissure."},"source_answer":"C","source_explanation":"Fresh blood covering the stool in the background history of prolonged constipation is most likely caused by internal hemorrhoid.\nTypical pattern of rectal bleeding in internal hemorrhoids is usually associated with a bowel movement. Bright-red blood typically coats the stool at the end of defecation. Blood may also drip into the toilet bowl or stain toilet paper. Hemorrhoidal\nbleeding is almost always painless, and painful defecation prompts investigation for other causes such as anorectal fissures.\nAlthough the pattern of rectal bleeding in this man is more likely to have been caused by hemorrhoids, overt or occult rectal bleeding should not be merely attributed to hemorrhoids until other less common but more serious causes of rectal bleeding\nhave been excluded by endoscopic testing. Flexible sigmoidoscopy or anoscopy in low-risk younger patients or colonoscopy in most other patients establishes the diagnosis of hemorrhoids, and excludes other causes of bleeding such as colitis,\ntumors, polyps, or vascular malformations.\n(Option A) Presence of rectal bleeding in this patient should also raise suspicion against colorectal cancer. However, this diagnosis is less likely because firstly, there are no other suggestive findings such as weight loss, altering bowel habits, etc. and\nsecondly, hemorrhoids are more common than cancers statistically.\n(Options B and E) External hemorrhoid and anal fissure are associated with significant anal pain and are very unlikely to be the diagnosis in this patient who has no pain on defecation.\n(Option D) Anorectal fistulae are associated with soiling rather than rectal bleeding. It is unlikely that painless fresh rectal bleeding is the only presentation of anorectal fistulae.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"b311c5c5dab587c7e873cb70ae2a26b34951026a","duplicate_group_id":"exact-b311c5c5dab5","duplicate_sources":[{"record_id":"fd8f4067e18fe4070ccd","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":550,"source_qid":"901"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,so