INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d85319850095a59ba0f8','Amedex 2023.pdf','555','Mixed/Unclassified','You prescribed triple therapy against Helicobacter pylori with clarithromycin, amoxicillin and esomperazole for a 42-year-old patient of yours after his test results came back positive for the infection and you considered it as the cause of his
intractable dyspepsia. One week after completion of the treatment, he comes back with reduced yet persisting symptoms. You arrange for a breath urea test. The result of the test is positive indicating treatment failure. Which one of the following is
the most likely cause of the failed treatment?','{"A":"Resistance to clarithromycin.","B":"Resistance to amoxicillin.","C":"False positive breath urea test result.","D":"Poor adherence to the therapy.","E":"Misdiagnosis of the cause of dyspepsia."}','A','Triple therapy with clarithromycin, amoxicillin and a proton pump inhibitor (PPI) for 7-14 days is the regimen of choice for treatment of H.pylori infection with over 90% response. Clarithromycin is the most effective antibiotic against H.pylori.
The most common cause of treatment failure with this regimen is the increasing rates of resistance of H.pylori to clarithromycin. This resistance cannot be overcome by dose increase or lengthening the duration of therapy.
NOTE - In those with penicillin hypersensitivity, in whom amoxicillin cannot be used, metronidazole can replace amoxicillin. So the regimen whould be a combination of metronidazole, clarithromycin and a PPI. I such cases, resistance to
either metronidazole or clarithromycin, or even both, can be the cause of treatment failure.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"933","duplicate_group_id":"exact-37794044b1cc","duplicate_sources":[{"record_id":"d85319850095a59ba0f8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":555,"source_qid":"933"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"d85319850095a59ba0f8","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":555,"source_qid":"933","domain_hint":"Mixed/Unclassified","stem":"You prescribed triple therapy against Helicobacter pylori with clarithromycin, amoxicillin and esomperazole for a 42-year-old patient of yours after his test results came back positive for the infection and you considered it as the cause of his\nintractable dyspepsia. One week after completion of the treatment, he comes back with reduced yet persisting symptoms. You arrange for a breath urea test. The result of the test is positive indicating treatment failure. Which one of the following is\nthe most likely cause of the failed treatment?","options":{"A":"Resistance to clarithromycin.","B":"Resistance to amoxicillin.","C":"False positive breath urea test result.","D":"Poor adherence to the therapy.","E":"Misdiagnosis of the cause of dyspepsia."},"source_answer":"A","source_explanation":"Triple therapy with clarithromycin, amoxicillin and a proton pump inhibitor (PPI) for 7-14 days is the regimen of choice for treatment of H.pylori infection with over 90% response. Clarithromycin is the most effective antibiotic against H.pylori.\nThe most common cause of treatment failure with this regimen is the increasing rates of resistance of H.pylori to clarithromycin. This resistance cannot be overcome by dose increase or lengthening the duration of therapy.\nNOTE - In those with penicillin hypersensitivity, in whom amoxicillin cannot be used, metronidazole can replace amoxicillin. So the regimen whould be a combination of metronidazole, clarithromycin and a PPI. I such cases, resistance to\neither metronidazole or clarithromycin, or even both, can be the cause of treatment failure.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["antibiotic","dose","duration","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"37794044b1cc32524d0443357c273e2410ee1744","duplicate_group_id":"exact-37794044b1cc","duplicate_sources":[{"record_id":"d85319850095a59ba0f8","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":555,"source_qid":"933"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=ex